package theme

import (
	"encoding/json"
	"fmt"
	"image/color"
	"io"
	"strconv"
	"strings"

	"fyne.io/fyne/v2"
)

// jsonTheme wraps a theme with JSON overrides
type jsonTheme struct {
	colors      map[string]string
	colorsDark  map[string]string
	colorsLight map[string]string
	sizes       map[string]float32
	fonts       map[string]string
	icons       map[string]string
}

// FromJSON parses a JSON theme definition and returns a fyne.Theme.
// If parsing fails, returns the default theme along with the error.
//
// The JSON structure supports:
//   - "Colors": map of color name to hex string (applied regardless of variant)
//   - "Colors-dark": map of color name to hex string (dark variant only)
//   - "Colors-light": map of color name to hex string (light variant only)
//   - "Sizes": map of size name to float32
//   - "Fonts": map of font style ("regular", "bold", "boldItalic", "monospace") to URI
//   - "Icons": map of icon name to URI
//
// Hex colors support 3, 4, 6, or 8 digit formats with optional # prefix.
//
// Since: 2.2
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader parses a JSON theme from an io.Reader.
// See FromJSON for format details.
//
// Since: 2.2
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var raw map[string]interface{}
	if err := json.NewDecoder(r).Decode(&raw); err != nil {
		return DarkTheme(), err
	}

	theme := &jsonTheme{
		colors:      make(map[string]string),
		colorsDark:  make(map[string]string),
		colorsLight: make(map[string]string),
		sizes:       make(map[string]float32),
		fonts:       make(map[string]string),
		icons:       make(map[string]string),
	}

	// Parse generic colors
	if colorsRaw, ok := raw["Colors"].(map[string]interface{}); ok {
		for name, val := range colorsRaw {
			if hexStr, ok := val.(string); ok {
				theme.colors[name] = hexStr
			}
		}
	}

	// Parse dark variant colors
	if colorsDarkRaw, ok := raw["Colors-dark"].(map[string]interface{}); ok {
		for name, val := range colorsDarkRaw {
			if hexStr, ok := val.(string); ok {
				theme.colorsDark[name] = hexStr
			}
		}
	}

	// Parse light variant colors
	if colorsLightRaw, ok := raw["Colors-light"].(map[string]interface{}); ok {
		for name, val := range colorsLightRaw {
			if hexStr, ok := val.(string); ok {
				theme.colorsLight[name] = hexStr
			}
		}
	}

	// Parse sizes
	if sizesRaw, ok := raw["Sizes"].(map[string]interface{}); ok {
		for name, val := range sizesRaw {
			if floatVal, ok := val.(float64); ok {
				theme.sizes[name] = float32(floatVal)
			}
		}
	}

	// Parse fonts
	if fontsRaw, ok := raw["Fonts"].(map[string]interface{}); ok {
		for name, val := range fontsRaw {
			if uriStr, ok := val.(string); ok {
				theme.fonts[name] = uriStr
			}
		}
	}

	// Parse icons
	if iconsRaw, ok := raw["Icons"].(map[string]interface{}); ok {
		for name, val := range iconsRaw {
			if uriStr, ok := val.(string); ok {
				theme.icons[name] = uriStr
			}
		}
	}

	return theme, nil
}

// Color looks up a color by name and variant, with fallback to default theme
func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	// Check variant-specific colors first
	var hexStr string
	var found bool

	if variant == fyne.VariantDark {
		hexStr, found = t.colorsDark[string(name)]
	} else if variant == fyne.VariantLight {
		hexStr, found = t.colorsLight[string(name)]
	}

	// Fall back to generic colors
	if !found {
		hexStr, found = t.colors[string(name)]
	}

	// If found, parse hex color
	if found {
		col, err := parseHexColor(hexStr)
		if err == nil {
