)

// sprintf is a String binding that formats values from other bindings using fmt.Sprintf
type sprintf struct {
	base
	format string
	values []DataItem
}

// NewSprintf creates a new String binding that formats the values from the provided bindings
// using fmt.Sprintf with the given format string. When any of the source bindings change,
// this binding updates with the newly formatted string.
//
// Example:
//   name := binding.NewString()
//   name.Set("Alice")
//   age := binding.NewInt()
//   age.Set(30)
//   formatted := binding.NewSprintf("Name: %s, Age: %d", name, age)
//   // formatted.Get() returns "Name: Alice, Age: 30"
//
// Since: 2.2
func NewSprintf(format string, bindings ...DataItem) String {
	s := &sprintf{
		format: format,
		values: bindings,
	}

	// Listen to all source bindings for changes
	for _, b := range bindings {
		b.AddListener(s)
	}

	return s
}

// Get returns the formatted string using the current values of all source bindings
func (s *sprintf) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	values := make([]interface{}, len(s.values))
	for i, b := range s.values {
		var err error
		switch v := b.(type) {
		case Bool:
			values[i], err = v.Get()
		case Bytes:
			values[i], err = v.Get()
		case Float:
			values[i], err = v.Get()
		case Int:
			values[i], err = v.Get()
		case Rune:
			values[i], err = v.Get()
		case String:
			values[i], err = v.Get()
		case URI:
			uri, err := v.Get()
			if err != nil {
				return "", err
			}
			if uri != nil {
				values[i] = uri.String()
			} else {
				values[i] = ""
			}
			continue
		case Untyped:
			values[i], err = v.Get()
		default:
			// Fallback for unknown types
			if u, ok := b.(Untyped); ok {
				values[i], err = u.Get()
			} else {
				values[i] = b
			}
		}
		if err != nil {
			return "", err
		}
	}

	return fmt.Sprintf(s.format, values...), nil
}

// Set parses the string back using fmt.Sscanf and sets each source binding to the parsed value.
// Bytes cannot be round-tripped (returns an error), URI is parsed via storage.ParseURI.
func (s *sprintf) Set(str string) error {
	s.lock.Lock()
	defer s.lock.Unlock()

	// Check if any binding is Bytes (cannot be round-tripped)
	for _, b := range s.values {
		if _, ok := b.(Bytes); ok {
			return fmt.Errorf("cannot round-trip Bytes binding through sprintf")
		}
	}

	// Prepare pointers to receive parsed values
	values := make([]interface{}, len(s.values))
	for i, b := range s.values {
		switch b.(type) {
		case Bool:
			var val bool
			values[i] = &val
		case Float:
			var val float64
			values[i] = &val
		case Int:
			var val int
			values[i] = &val
		case Rune:
			var val rune
			values[i] = &val
		case String:
			var val string
			values[i] = &val
		case URI:
			var val string
			values[i] = &val
		case Untyped:
			var val interface{}
			values[i] = &val
		default:
			return fmt.Errorf("unsupported binding type for Set")
		}
	}

	// Parse the string using Sscanf
	n, err := fmt.Sscanf(str, s.format, values...)
	if err != nil {
		return err
	}
	if n != len(s.values) {
		return fmt.Errorf("parsed %d values, expected %d", n, len(s.values))
	}

	// Set each binding with the parsed value
	for i, b := range s.values {
		switch v := b.(type) {
		case Bool:
			if err := v.Set(*values[i].(*bool)); err != nil {
				return err
			}
		case Float:
			if err := v.Set(*values[i].(*float64)); err != nil {
				return err
			}
		case Int:
			if err := v.Set(*values[i].(*int)); err != nil {
				return err
			}
		case Rune:
			if err := v.Set(*values[i].(*rune)); err != nil {
				return err
			}
		case String:
			if err := v.Set(*values[i].(*string)); err != nil {
				return err
			}
		case URI:
			uriStr := *values[i].(*string)
			uri, err := storage.ParseURI(uriStr)
			if err != nil {
				return err
			}
			if err := v.Set(uri); err != nil {
				return err
			}
		case Untyped:
			if err := v.Set(*values[i].(*interface{})); err != nil {
				return err
			}
		}
	}

	s.trigger()
	return nil
}

// DataChanged is called when any source binding changes, triggering update to listeners
func (s *sprintf) DataChanged() {
	s.trigger()
}

