package validation

import "fyne.io/fyne/v2"

// allStrings is a validator that checks if the input string matches any of the allowed strings.
type allStrings struct {
	allowed []string
}

// Validate checks if the input string is one of the allowed strings.
// Returns an error if the string is not in the allowed list.
func (v *allStrings) Validate(text string) error {
	for _, allowed := range v.allowed {
		if text == allowed {
			return nil
		}
	}
	return NewAllStringsError(text, v.allowed)
}

// NewAllStrings creates a new validator that checks if the input string matches
// any of the provided allowed strings. This is useful for validating against
// a predefined set of acceptable values (e.g., enum-like validation).
//
// Example:
//   validator := validation.NewAllStrings([]string{"red", "green", "blue"})
//   entry.Validator = validator
//
// Since: 2.2
func NewAllStrings(allowed []string) fyne.StringValidator {
	return &allStrings{allowed: allowed}
}

// allStringsError is the validation error returned when input doesn't match any allowed string.
type allStringsError struct {
	input   string
	allowed []string
}

// Error returns the error message for the validation failure.
func (e *allStringsError) Error() string {
	return "Input does not match any allowed value"
}

// NewAllStringsError creates a new validation error for the allStrings validator.
func NewAllStringsError(input string, allowed []string) error {
	return &allStringsError{input: input, allowed: allowed}
}

