package desktop

import "fyne.io/fyne/v2"

// App interface extends the standard fyne.App interface with desktop-specific capabilities.
// This interface provides access to system tray functionality and other desktop features.
//
// Since: 2.2
type App interface {
	fyne.App

	// SystemTrayMenu returns the system tray menu for this application.
	// The menu will be displayed when the user interacts with the system tray icon.
	// Returns nil if no system tray menu is set.
	//
	// Since: 2.2
	SystemTrayMenu() *fyne.Menu

	// SetSystemTrayIcon sets the icon to be displayed in the system tray.
	// Pass nil to remove the system tray icon.
	//
	// Since: 2.2
	SetSystemTrayIcon(icon fyne.Resource)

	// SetSystemTrayTooltip sets the tooltip text that appears when hovering
	// over the system tray icon.
	//
	// Since: 2.2
	SetSystemTrayTooltip(tooltip string)
}

